#pragma once
namespace { namespace streaming {
inline bool request_id(const std::string& s){return !s.empty()&&s.size()<=64&&std::all_of(s.begin(),s.end(),[](unsigned char c){return std::isalnum(c)||c=='_'||c=='-';});}
template<class Backend>
void run_requests(Backend& backend,streamio::Dataset& source,boexp::Worker& worker,const fs::path& dir,unsigned reps,unsigned warm,bool ascending){
 require(reps>=1&&reps<=20&&warm<=3&&!fs::exists(dir),"stream request counts/results");fs::create_directories(dir/"outputs");
 std::ofstream whole(dir/"iterations.csv"),groups(dir/"groups.csv"),timeline(dir/"timeline.csv"),resources(dir/"resources.jsonl");for(auto* f:{&whole,&groups,&timeline,&resources})*f<<std::fixed<<std::setprecision(6);
 whole<<"repetition,warmup,export_only,groups,request_wall_ms,shared_validate_ms,group_wall_sum_ms,pack_work_sum_ms,execute_envelope_sum_ms,verify_work_sum_ms,verified_words\n";
 groups<<"repetition,warmup,export_only,ordinal,group,group_wall_ms,pack_work_ms,execute_envelope_sum_ms,verify_work_ms,output_save_work_ms,verified_words\n";
 timeline<<"repetition,warmup,export_only,group,chunk,bank,stage,lane,begin_ms,end_ms\n";std::vector<double> walls;
 try{for(unsigned rep=0;rep<reps+warm+1;++rep){const bool w=rep<warm,exporting=rep==reps+warm;auto counters=streamio::Metrics::now();auto start=Clock::now();source.begin_request();double shared=ms(start,Clock::now()),pack=0,exec=0,verify=0,groupwall=0;uint64_t words=0;std::ostringstream gr;gr<<std::fixed<<std::setprecision(6);std::vector<boexp::Replay> traces;std::vector<unsigned> ids;traces.reserve(6);ids.reserve(6);
  for(unsigned ordinal=0;ordinal<6;++ordinal){unsigned g=ascending?ordinal:5-ordinal;auto out=dir/"outputs"/("group_"+std::to_string(g));if(exporting)fs::create_directories(out);backend.select_group(g,out);auto r=boexp::run_finish_overlap(backend,source.dimensions.chunks,worker,exporting);double p=0,e=0,v=0,save=0;for(const auto& f:r.frames)for(unsigned j=0;j<f.count;++j){const auto& span=f.spans[j];auto duration=span.end-span.begin;if(std::strcmp(span.name,"pack_A_check_shared_B")==0)p+=duration;else if(std::strcmp(span.name,"execute")==0)e+=duration;else if(std::strcmp(span.name,"verify")==0)v+=duration;else if(std::strcmp(span.name,"output_save")==0)save+=duration;}groupwall+=r.wall_ms;pack+=p;exec+=e;verify+=v;words+=source.dimensions.chunks*source.shape.output_words();gr<<rep<<','<<w<<','<<exporting<<','<<ordinal<<','<<g<<','<<r.wall_ms<<','<<p<<','<<e<<','<<v<<','<<save<<','<<source.dimensions.chunks*source.shape.output_words()<<'\n';ids.push_back(g);traces.push_back(std::move(r));}
  source.end_request();auto wall=ms(start,Clock::now());auto after=streamio::Metrics::now();require(words==source.verified_words(),"stream full-six coverage");
  // Formatting/flushing the detailed trace is outside the measured request.
  for(unsigned g=0;g<traces.size();++g)for(const auto& f:traces[g].frames)for(unsigned j=0;j<f.count;++j){const auto& s=f.spans[j];timeline<<rep<<','<<w<<','<<exporting<<','<<ids[g]<<','<<f.chunk<<','<<f.bank<<','<<s.name<<','<<s.lane<<','<<s.begin<<','<<s.end<<'\n';}
  whole<<rep<<','<<w<<','<<exporting<<",6,"<<wall<<','<<shared<<','<<groupwall<<','<<pack<<','<<exec<<','<<verify<<','<<words<<'\n';groups<<gr.str();resources<<"{\"repetition\":"<<rep<<",\"warmup\":"<<w<<",\"export_only\":"<<exporting<<",\"process_metrics\":"<<after.delta_json(counters)<<"}\n";for(auto* f:{&whole,&groups,&timeline,&resources}){f->flush();require(bool(*f),"stream request result write");}
  if(!w&&!exporting)walls.push_back(wall);std::cout<<"PASS_STREAM_SIX_GROUPS backend="<<Backend::execution_backend<<" repetition="<<rep<<" warmup="<<w<<" export_only="<<exporting<<" request_wall_ms="<<wall<<" checked_words="<<words<<'\n'<<std::flush;
 }}catch(...){backend.cancel();worker.close();source.cancel_request();throw;}
 std::ofstream summary(dir/"summary.json");summary<<std::setprecision(12)<<"{\"status\":\"PASS_STREAM_SIX_GROUPS_PENDING_GROUND_RETURN\",\"execution_backend\":\""<<Backend::execution_backend<<"\",\"measured\":"<<reps<<",\"warmups\":"<<warm<<",\"export_replays\":1,\"request_wall_median_ms\":"<<median(walls)<<",\"protocol\":\"stream_request_v1\",\"shared_validation_inside_each_request\":true,\"stage_work_is_not_wall\":true,\"scope\":\"All six verified raw MACs including per-request shared validation and mapped pack/read faults, no whole-group heap cache. Setup and separate export retained. Not pure device cycles or original h_s.4 live end-to-end latency.\"}\n";summary.close();require(bool(summary),"stream request summary write");
}
template<class Backend>
void fixture_service(Backend& backend,streamio::Dataset& source,boexp::Worker& worker,const fs::path& root){
 require(!fs::exists(root),"new fixture service root required");fs::create_directories(root);std::cout<<"STREAM_READY backend="<<Backend::execution_backend<<" fixture_only=1"<<'\n'<<std::flush;std::string line;
 while(std::getline(std::cin,line)){if(line=="QUIT"){std::cout<<"STREAM_STOPPED\n"<<std::flush;return;}require(line.size()<=256,"oversized fixture service command");std::istringstream s(line);std::string op,id,order,extra;unsigned reps,warm;require(bool(s>>op>>id>>reps>>warm>>order)&&!(s>>extra)&&op=="RUN"&&request_id(id)&&(order=="descending"||order=="ascending"),"fixture service protocol");run_requests(backend,source,worker,root/id,reps,warm,order=="ascending");std::cout<<"STREAM_DONE "<<id<<'\n'<<std::flush;}
} }
}
